/// Bumped whenever generated code needs a newer runtime API.
public let GENCODE_VERSION = 1

/// The runtime cannot serve code generated for a different runtime API.
public struct GencodeVersionMismatch: Error, CustomStringConvertible {
    public let generated: Int

    public var description: String {
        "code generated by protoc-gen-mcp needs runtime API version \(generated), but ProtocGenMCPRuntime "
            + "provides \(GENCODE_VERSION); regenerate the code or use a matching runtime"
    }
}

/// Fails registration when generated code targets a different runtime API.
public func checkGencodeVersion(_ version: Int) throws {
    if version != GENCODE_VERSION {
        throw GencodeVersionMismatch(generated: version)
    }
}
